import { existsSync, readdirSync } from 'node:fs'
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, join, relative } from 'node:path'
import { Context, Service } from 'cordis'
import { Awaitable } from 'cosmokit'
import { idle } from './start.ts'
import { Refresher, winPath } from './utils/index.ts'

declare module 'cordis' {
  interface Context {
    app: App
  }

  interface Events {
    /**
     * The generated files were written.
     * @mode emit
     */
    'app/generate'(): void
  }
}

const HEADER = '// This file is generated by Cormi. Do not edit.\n'

function withHeader(path: string, content: string) {
  if (path.endsWith('.d.ts')) return HEADER + content
  if (/\.[cm]?[jt]sx?$/.test(path)) return '// @ts-nocheck\n' + HEADER + content
  return content
}

function listFiles(dir: string, base = dir): string[] {
  if (!existsSync(dir)) return []
  return readdirSync(dir, { withFileTypes: true }).flatMap((dirent) => {
    const path = join(dir, dirent.name)
    return dirent.isDirectory() ? listFiles(path, base) : [winPath(relative(base, path))]
  })
}

async function writeIfChanged(path: string, content: string) {
  // unchanged files keep their mtime, so the bundler does not reload them
  const current = await readFile(path, 'utf8').catch(() => undefined)
  if (current === content) return
  await mkdir(dirname(path), { recursive: true })
  await writeFile(path, content)
}

/**
 * The app as it is bundled (`ctx.app`).
 *
 * Node plugins contribute browser plugins with `entry()` (like koishi's
 * `ctx.console.addEntry()`), global imports with `import()`, generated modules
 * with `file()` and server bundle modules with `server()`. The generated
 * directory (`src/.cormi`) is rewritten whenever a contribution is added or
 * disposed, once the plugins being loaded have settled; files nobody
 * registers anymore are removed.
 */
export class App extends Service {
  /** browser plugins, mounted in registration order */
  entries = new Set<App.Entry>()
  /** side-effect imports evaluated before the browser plugins */
  imports = new Set<App.Import>()
  /** modules of the server bundle, exported as `modules[key]` */
  servers = new Map<string, string>()

  private _files = new Map<string, App.Content>()
  private _written = new Set<string>()
  private _refresher: Refresher

  constructor(ctx: Context) {
    super(ctx, 'app')
    this._refresher = new Refresher(() => this._generate(), 20, error => ctx.logger('app').error(error))
  }

  /** the generated directory */
  get dir() {
    return this.ctx.cormi.paths.tmp
  }

  /** the browser entry module, generated by the renderer */
  get clientEntry() {
    return winPath(join(this.dir, 'entry.tsx'))
  }

  /** the server entry module, generated by the renderer */
  get serverEntry() {
    return winPath(join(this.dir, 'server.tsx'))
  }

  /** paths of the registered generated files, relative to `dir` */
  get files() {
    return [...this._files.keys()]
  }

  * [Service.init]() {
    // files left by a previous run are removed by the first generation
    this._written = new Set(listFiles(this.dir))
    yield () => this._refresher.dispose()
  }

  /**
   * Mount a browser plugin. The module default-exports `(ctx, config) => void`
   * (or a cordis plugin object); `config` must be serializable to JSON.
   *
   * Packages should pass their own specifier (`@scope/plugin-foo/client`)
   * rather than a file path, so the app and the entry import the same module.
   */
  entry(module: string, config?: any) {
    const entry: App.Entry = { file: winPath(module), config }
    return this._register(this.entries, entry, `ctx.app.entry(${JSON.stringify(entry.file)})`)
  }

  /** Import a module (an absolute path or a specifier) for its side effects before the app starts. */
  import(source: string) {
    return this._register(this.imports, { source: winPath(source) }, `ctx.app.import(${JSON.stringify(source)})`)
  }

  /**
   * Generate `src/.cormi/<path>`. A function is called on every generation, so
   * it may read state that changes over time; returning `undefined` leaves the
   * file out. Namespace the path with your plugin name (`plugin-foo/index.ts`):
   * two registrations of one path conflict.
   */
  file(path: string, content: App.Content) {
    path = winPath(path)
    return this.ctx.effect(() => {
      if (this._files.has(path)) throw new Error(`generated file ${path} is registered twice`)
      this._files.set(path, content)
      this.refresh()
      return () => {
        this._files.delete(path)
        this.refresh()
      }
    }, `ctx.app.file(${JSON.stringify(path)})`)
  }

  /** Bundle a module into the server entry, exported as `modules[key]`. */
  server(key: string, file: string) {
    return this.ctx.effect(() => {
      if (this.servers.has(key)) throw new Error(`server module ${key} is registered twice`)
      this.servers.set(key, winPath(file))
      this.refresh()
      return () => {
        this.servers.delete(key)
        this.refresh()
      }
    }, `ctx.app.server(${JSON.stringify(key)})`)
  }

  /** Regenerate the files soon. */
  refresh() {
    this._refresher.schedule()
  }

  /** Wait for a pending generation. */
  flush() {
    return this._refresher.flush()
  }

  private _register<T>(set: Set<T>, value: T, label: string) {
    return this.ctx.effect(() => {
      set.add(value)
      this.refresh()
      return () => {
        set.delete(value)
        this.refresh()
      }
    }, label)
  }

  private async _generate() {
    // plugins loading right now are about to register: generate once for all of them
    await idle(this.ctx)
    const written = new Set<string>()
    for (const [path, content] of this._files) {
      try {
        const text = typeof content === 'function' ? await content() : content
        // `undefined`: the file is not needed now
        if (text === undefined) continue
        await writeIfChanged(join(this.dir, path), withHeader(path, text))
        written.add(path)
      } catch (error) {
        this.ctx.logger('app').error('failed to generate %s', path)
        this.ctx.logger('app').error(error)
        // keep the previous version instead of deleting it
        if (this._written.has(path)) written.add(path)
      }
    }
    for (const path of this._written) {
      if (!written.has(path)) await rm(join(this.dir, path), { force: true })
    }
    this._written = written
    this.ctx.emit('app/generate')
  }
}

export namespace App {
  export interface Entry {
    /** absolute path or package specifier of the browser plugin module */
    file: string
    /** config passed to the browser plugin */
    config?: any
  }

  export interface Import {
    source: string
  }

  export type Content = string | (() => Awaitable<string | undefined>)
}
